function(container, apiUrl, tables) {
    // 業務ロジックモジュールのインポート（グローバルスコープから取得）
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.aiLogic || {};

    let editingId = null;

    // 売上データ一覧の読み込み
    function loadSalesData() {
        window.aivicApi.list('sales_data', {})
            .then(data => {
                try {
                    // 業務ロジックを使用してデータを収集・分類
                    const collectedData = collectSalesData ? collectSalesData(data) : data;

                    const tbody = container.querySelector('#salesDataTable tbody');
                    if (tbody) {
                        tbody.innerHTML = '';
                        collectedData.forEach(item => {
                            const row = document.createElement('tr');
                            row.innerHTML = `
                                <td>${item.date || ''}</td>
                                <td>${item.product_name || ''}</td>
                                <td>${item.store_name || ''}</td>
                                <td>${item.sales_amount || 0}</td>
                                <td>${item.quantity || 0}</td>
                                <td>
                                    <button class="btn-edit" data-id="${item.id}">編集</button>
                                    <button class="btn-delete" data-id="${item.id}">削除</button>
                                </td>
                            `;
                            tbody.appendChild(row);
                        });

                        // 編集・削除ボタンのイベントハンドラー
                        tbody.querySelectorAll('.btn-edit').forEach(btn => {
                            btn.addEventListener('click', (e) => {
                                const id = e.target.dataset.id;
                                editSalesData(id);
                            });
                        });

                        tbody.querySelectorAll('.btn-delete').forEach(btn => {
                            btn.addEventListener('click', (e) => {
                                const id = e.target.dataset.id;
                                deleteSalesData(id);
                            });
                        });
                    }
                } catch (error) {
                    window.aivicNotify.error('データ処理中にエラーが発生しました: ' + error.message);
                }
            })
            .catch(error => {
                window.aivicNotify.error('売上データの読み込みに失敗しました: ' + error.message);
            });
    }

    // 売上データの保存
    function saveSalesData() {
        try {
            const formData = {
                date: container.querySelector('#salesDate')?.value || '',
                product_name: container.querySelector('#productName')?.value || '',
                store_name: container.querySelector('#storeName')?.value || '',
                sales_amount: parseFloat(container.querySelector('#salesAmount')?.value || 0),
                quantity: parseInt(container.querySelector('#quantity')?.value || 0)
            };

            // 業務ロジックでデータ検証
            const validatedData = filterValidProductData ? filterValidProductData([formData]) : [formData];

            if (validatedData.length === 0) {
                window.aivicNotify.error('入力データが無効です');
                return;
            }

            const apiCall = editingId ? 
                window.aivicApi.update('sales_data', editingId, validatedData[0]) :
                window.aivicApi.save('sales_data', validatedData[0]);

            apiCall.then(() => {
                window.aivicNotify.success(editingId ? '売上データを更新しました' : '売上データを保存しました');
                clearForm();
                loadSalesData();
            }).catch(error => {
                window.aivicNotify.error('保存に失敗しました: ' + error.message);
            });

        } catch (error) {
            window.aivicNotify.error('データ処理中にエラーが発生しました: ' + error.message);
        }
    }

    // 売上データの編集
    function editSalesData(id) {
        window.aivicApi.list('sales_data', { id: id })
            .then(data => {
                if (data && data.length > 0) {
                    const item = data[0];
                    editingId = id;

                    const dateInput = container.querySelector('#salesDate');
                    const productInput = container.querySelector('#productName');
                    const storeInput = container.querySelector('#storeName');
                    const amountInput = container.querySelector('#salesAmount');
                    const quantityInput = container.querySelector('#quantity');

                    if (dateInput) dateInput.value = item.date || '';
                    if (productInput) productInput.value = item.product_name || '';
                    if (storeInput) storeInput.value = item.store_name || '';
                    if (amountInput) amountInput.value = item.sales_amount || '';
                    if (quantityInput) quantityInput.value = item.quantity || '';

                    const saveBtn = container.querySelector('#saveSalesData');
                    if (saveBtn) saveBtn.textContent = '更新';
                }
            })
            .catch(error => {
                window.aivicNotify.error('データの取得に失敗しました: ' + error.message);
            });
    }

    // 売上データの削除
    function deleteSalesData(id) {
        if (confirm('このデータを削除しますか？')) {
            window.aivicApi.delete('sales_data', id)
                .then(() => {
                    window.aivicNotify.success('売上データを削除しました');
                    loadSalesData();
                })
                .catch(error => {
                    window.aivicNotify.error('削除に失敗しました: ' + error.message);
                });
        }
    }

    // フォームのクリア
    function clearForm() {
        editingId = null;
        const inputs = container.querySelectorAll('#salesDate, #productName, #storeName, #salesAmount, #quantity');
        inputs.forEach(input => input.value = '');

        const saveBtn = container.querySelector('#saveSalesData');
        if (saveBtn) saveBtn.textContent = '保存';
    }

    // 商品別分析
    function analyzeByProduct() {
        window.aivicApi.list('sales_data', {})
            .then(data => {
                try {
                    const classifiedData = classifySalesDataByProduct ? classifySalesDataByProduct(data) : data;

                    const resultDiv = container.querySelector('#analysisResult');
                    if (resultDiv) {
                        let html = '<h4>商品別売上分析</h4>';
                        Object.keys(classifiedData).forEach(product => {
                            const productData = classifiedData[product];
                            const totalSales = productData.reduce((sum, item) => sum + (item.sales_amount || 0), 0);
                            const totalQuantity = productData.reduce((sum, item) => sum + (item.quantity || 0), 0);
                            html += `<p>${product}: 売上 ${totalSales.toLocaleString()}円, 数量 ${totalQuantity}個</p>`;
                        });
                        resultDiv.innerHTML = html;
                    }
                } catch (error) {
                    window.aivicNotify.error('商品別分析中にエラーが発生しました: ' + error.message);
                }
            })
            .catch(error => {
                window.aivicNotify.error('データの取得に失敗しました: ' + error.message);
            });
    }

    // 店舗別分析
    function analyzeByStore() {
        window.aivicApi.list('sales_data', {})
            .then(data => {
                try {
                    const classifiedData = classifySalesDataByStore ? classifySalesDataByStore(data) : data;

                    const resultDiv = container.querySelector('#analysisResult');
                    if (resultDiv) {
                        let html = '<h4>店舗別売上分析</h4>';
                        Object.keys(classifiedData).forEach(store => {
                            const storeData = classifiedData[store];
                            const totalSales = storeData.reduce((sum, item) => sum + (item.sales_amount || 0), 0);
                            const totalQuantity = storeData.reduce((sum, item) => sum + (item.quantity || 0), 0);
                            html += `<p>${store}: 売上 ${totalSales.toLocaleString()}円, 数量 ${totalQuantity}個</p>`;
                        });
                        resultDiv.innerHTML = html;
                    }
                } catch (error) {
                    window.aivicNotify.error('店舗別分析中にエラーが発生しました: ' + error.message);
                }
            })
            .catch(error => {
                window.aivicNotify.error('データの取得に失敗しました: ' + error.message);
            });
    }

    // 相関分析
    function performCorrelationAnalysis() {
        Promise.all([
            window.aivicApi.list('sales_data', {}),
            window.aivicApi.list('weather_data', {}),
            window.aivicApi.list('event_data', {}),
            window.aivicApi.list('seasonal_data', {})
        ]).then(([salesData, weatherData, eventData, seasonalData]) => {
            try {
                const weatherCorrelation = analyzeCorrelationSalesWeather ? 
                    analyzeCorrelationSalesWeather(salesData, weatherData) : null;
                const eventCorrelation = analyzeCorrelationSalesEvent ? 
                    analyzeCorrelationSalesEvent(salesData, eventData) : null;
                const seasonalCorrelation = analyzeCorrelationSalesSeason ? 
                    analyzeCorrelationSalesSeason(salesData, seasonalData) : null;

                const resultDiv = container.querySelector('#analysisResult');
                if (resultDiv) {
                    let html = '<h4>相関分析結果</h4>';
                    if (weatherCorrelation) {
                        html += `<p>天候との相関: ${weatherCorrelation.correlation || 'N/A'}</p>`;
                    }
                    if (eventCorrelation) {
                        html += `<p>イベントとの相関: ${eventCorrelation.correlation || 'N/A'}</p>`;
                    }
                    if (seasonalCorrelation) {
                        html += `<p>季節との相関: ${seasonalCorrelation.correlation || 'N/A'}</p>`;
                    }
                    resultDiv.innerHTML = html;
                }
            } catch (error) {
                window.aivicNotify.error('相関分析中にエラーが発生しました: ' + error.message);
            }
        }).catch(error => {
            window.aivicNotify.error('データの取得に失敗しました: ' + error.message);
        });
    }

    // イベントハンドラーの設定
    const saveSalesBtn = container.querySelector('#saveSalesData');
    if (saveSalesBtn) {
        saveSalesBtn.addEventListener('click', saveSalesData);
    }

    const clearBtn = container.querySelector('#clearForm');
    if (clearBtn) {
        clearBtn.addEventListener('click', clearForm);
    }

    const analyzeProductBtn = container.querySelector('#analyzeByProduct');
    if (analyzeProductBtn) {
        analyzeProductBtn.addEventListener('click', analyzeByProduct);
    }

    const analyzeStoreBtn = container.querySelector('#analyzeByStore');
    if (analyzeStoreBtn) {
        analyzeStoreBtn.addEventListener('click', analyzeByStore);
    }

    const correlationBtn = container.querySelector('#performCorrelationAnalysis');
    if (correlationBtn) {
        correlationBtn.addEventListener('click', performCorrelationAnalysis);
    }

    const refreshBtn = container.querySelector('#refreshSalesData');
    if (refreshBtn) {
        refreshBtn.addEventListener('click', loadSalesData);
    }

    // 初期データ読み込み
    loadSalesData();
}
